package scaffold

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

// ModuleTraits are the facts about an existing module that the slice
// templates depend on.
type ModuleTraits struct {
	Name, ModulePath string
	Database, Grpc   bool
}

// DetectModule reads the traits of modules/<name> from its tree. It expects a
// module generated by `new module`.
func DetectModule(repoRoot, name string) (ModuleTraits, error) {
	dir := filepath.Join(repoRoot, "modules", name)
	if _, err := os.Stat(filepath.Join(dir, name+".go")); err != nil {
		return ModuleTraits{}, fmt.Errorf("detect module %q: %w", name, err)
	}

	data, err := os.ReadFile(filepath.Join(dir, "go.mod"))
	if err != nil {
		return ModuleTraits{}, fmt.Errorf("detect module %q: %w", name, err)
	}
	var modulePath string
	for line := range strings.SplitSeq(string(data), "\n") {
		if rest, ok := strings.CutPrefix(line, "module "); ok {
			modulePath = strings.TrimSpace(rest)

			break
		}
	}
	if modulePath == "" {
		return ModuleTraits{}, fmt.Errorf("detect module %q: no module line in go.mod", name)
	}

	return ModuleTraits{
		Name:       name,
		ModulePath: modulePath,
		Database:   isDir(filepath.Join(dir, "internal", "infra", "persistence")),
		Grpc:       isDir(filepath.Join(dir, "cmd", name)),
	}, nil
}

func isDir(path string) bool {
	info, err := os.Stat(path)

	return err == nil && info.IsDir()
}

// Apply stores the traits in vars under the keys the templates use.
func (t ModuleTraits) Apply(vars map[string]any) {
	vars["Name"] = t.Name
	vars["ModulePath"] = t.ModulePath
	vars["Database"] = t.Database
	vars["Grpc"] = t.Grpc
}

const stampLayout = "20060102150405"

var stampRe = regexp.MustCompile(`^(\d{14})(?:\D|$)`)

// MigrationStamps returns the timestamps for a slice's create and seed
// migrations: now (UTC), or one second after the highest 14-digit prefix in
// scriptsDir when that is later; seed is create plus one second.
func MigrationStamps(scriptsDir string, now time.Time) (create, seed string) {
	at := now.UTC().Truncate(time.Second)

	entries, _ := os.ReadDir(scriptsDir) // missing dir: no existing stamps
	for _, e := range entries {
		m := stampRe.FindStringSubmatch(e.Name())
		if m == nil {
			continue
		}
		if t, err := time.Parse(stampLayout, m[1]); err == nil && !t.Before(at) {
			at = t.Add(time.Second)
		}
	}

	return at.Format(stampLayout), at.Add(time.Second).Format(stampLayout)
}

// SliceReport lists what AddSlice could not wire: hand-written modules carry
// no markers and no bungen table list.
type SliceReport struct {
	Unwired       []Snippet // snippets whose marker was not found, Path relative to the module
	TableUnlisted string    // table to add to bungen's -t list by hand
}

// AddSlice renders the slice templates into the module named by vars, inserts
// the slice's snippets at the module's markers and lists its table for
// bungen. A missing marker or table list is reported, never an error.
// It does not run PostGenerate.
func AddSlice(sliceFS fs.FS, repoRoot string, vars map[string]any) (SliceReport, error) {
	name, _ := vars["Name"].(string)
	entity, _ := vars["Entity"].(string)
	moduleDir := filepath.Join(repoRoot, "modules", name)

	vars["TimestampCreate"], vars["TimestampSeed"] = MigrationStamps(
		filepath.Join(moduleDir, "internal", "infra", "persistence", "migrations", "scripts"), time.Now())

	if err := Render(sliceFS, repoRoot, vars); err != nil {
		return SliceReport{}, fmt.Errorf("render slice: %w", err)
	}

	snippets, err := RenderSnippets(vars)
	if err != nil {
		return SliceReport{}, fmt.Errorf("render snippets: %w", err)
	}

	var report SliceReport
	for _, s := range snippets {
		ok, err := InsertBefore(filepath.Join(moduleDir, s.Path), s.Marker, s.Text)
		// A hand-written module may lack the file altogether.
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return report, fmt.Errorf("wire slice: %w", err)
		}
		if !ok {
			report.Unwired = append(report.Unwired, s)
		}
	}

	if shape, _ := vars["Shape"].(string); shape != ShapeGateway {
		table := name + "." + entity
		ok, err := AppendBungenTable(filepath.Join(moduleDir, "mise.toml"), table)
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return report, fmt.Errorf("list the table for bungen: %w", err)
		}
		if !ok {
			report.TableUnlisted = table
		}
	}

	return report, nil
}
